package app.usspace.couple.v012;

import android.app.Activity;
import android.webkit.JavascriptInterface;
import android.webkit.WebView;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;
import com.google.firebase.firestore.*;
import org.json.*;
import java.time.Instant;
import java.util.*;

/** Separate category-scoped consent. No data enters common sync, notifications or travel. */
public final class PairedCareBridge {
    private static final List<String> CATEGORIES=Arrays.asList("steps","sleep","workouts","heartRate","cycleDates","cyclePredictions","cycleSymptoms","roster");
    private final Activity activity;private final WebView view;private final FirebaseFirestore db=FirebaseFirestore.getInstance();
    private final FirebaseAuth auth=FirebaseAuth.getInstance();private final FirebaseAuth.AuthStateListener authListener;
    private final List<ListenerRegistration> accountListeners=new ArrayList<>(),pairListeners=new ArrayList<>(),partnerListeners=new ArrayList<>();
    private final Map<String,Map<String,Object>> consents=new HashMap<>(),partnerData=new HashMap<>(),lastData=new HashMap<>();
    private final Map<String,Long> partnerRevisions=new HashMap<>();
    private final Map<String,ListenerRegistration> shareListeners=new HashMap<>();
    private void clearShareListeners(){for(ListenerRegistration l:shareListeners.values())l.remove();shareListeners.clear();}
    private final List<Map<String,Object>> events=new ArrayList<>(),sources=new ArrayList<>(),partnerEvents=new ArrayList<>();
    private volatile boolean refreshingJubilee;private boolean jubileeOwner;private long lastJubileeAttempt;
    private String uid="",pair="",partner="",error="";private Object ownerJoined,partnerJoined;private long epoch,pairEpoch;private boolean ready,closed,paired,consentReady;
    public PairedCareBridge(Activity a,WebView w){activity=a;view=w;authListener=x->activity.runOnUiThread(this::bind);auth.addAuthStateListener(authListener);}
    private String account(){FirebaseUser u=auth.getCurrentUser();return u==null?"":u.getUid();}
    private DocumentReference own(String collection,String id){return db.document("users/"+uid+"/"+collection+"/"+id);}
    private void remove(List<ListenerRegistration> list){for(ListenerRegistration l:list)l.remove();list.clear();}
    private void clearPair(){pairEpoch++;clearShareListeners();if(partnerRoster!=null){partnerRoster.remove();partnerRoster=null;}partnerRevisions.clear();remove(pairListeners);remove(partnerListeners);paired=false;jubileeOwner=false;partner="";ownerJoined=null;partnerJoined=null;partnerData.clear();partnerEvents.clear();}
    private void bind(){if(closed)return;String next=account();if(next.equals(uid)&&!accountListeners.isEmpty())return;epoch++;remove(accountListeners);clearPair();uid=next;pair="";consents.clear();consentReady=false;lastJubileeAttempt=0;lastData.clear();events.clear();sources.clear();error="";publish();if(uid.isEmpty())return;final long token=epoch;
      accountListeners.add(db.document("users/"+uid).addSnapshotListener(MetadataChanges.INCLUDE,(s,e)->{if(!active(token))return;if(e!=null||s==null||s.getMetadata().isFromCache()){clearPair();publish();return;}String nextPair=s.getString("coupleId");if(nextPair==null)nextPair="";if(!nextPair.equals(pair)||!paired){clearPair();pair=nextPair;if(!pair.isEmpty())watchPair(token);}publish();}));
      accountListeners.add(db.collection("users/"+uid+"/careConsent").addSnapshotListener(MetadataChanges.INCLUDE,(s,e)->{if(!active(token))return;consents.clear();consentReady=e==null&&s!=null&&!s.getMetadata().isFromCache()&&!s.getMetadata().hasPendingWrites();if(consentReady)for(DocumentSnapshot d:s.getDocuments())consents.put(d.getId(),d.getData());publish();for(String c:CATEGORIES)upload(c);}));
      accountListeners.add(db.collection("users/"+uid+"/rosterEvents").limit(450).addSnapshotListener((s,e)->{if(!active(token))return;events.clear();if(e==null&&s!=null)for(DocumentSnapshot d:s.getDocuments())events.add(d.getData());if(s!=null&&s.size()>=450)error="Roster display limit reached. Source refresh is unchanged.";publish();uploadRoster();}));
      accountListeners.add(db.collection("users/"+uid+"/rosterSources").limit(20).addSnapshotListener((s,e)->{if(!active(token))return;sources.clear();if(e==null&&s!=null)for(DocumentSnapshot d:s.getDocuments())sources.add(d.getData());publish();uploadRoster();}));
    }
    private boolean active(long token){return !closed&&epoch==token&&uid.equals(account());}
    private void watchPair(long token){final String expected=pair;
      pairListeners.add(db.document("couples/"+pair+"/usRoles/identity").addSnapshotListener(MetadataChanges.INCLUDE,(roles,issue)->{if(!active(token)||!expected.equals(pair))return;jubileeOwner=issue==null&&roles!=null&&roles.exists()&&!roles.getMetadata().isFromCache()&&uid.equals(roles.getString("alUid"));if(jubileeOwner&&ready&&System.currentTimeMillis()-lastJubileeAttempt>15*60000L)refreshJubilee(uid);}));
      pairListeners.add(db.document("couples/"+pair).addSnapshotListener(MetadataChanges.INCLUDE,(room,e)->{if(!active(token)||!expected.equals(pair))return;if(e!=null||room==null||room.getMetadata().isFromCache()||!Long.valueOf(2).equals(room.getLong("memberCount"))){paired=false;partnerData.clear();partnerEvents.clear();publish();}}));
      pairListeners.add(db.collection("couples/"+pair+"/members").limit(3).addSnapshotListener(MetadataChanges.INCLUDE,(s,e)->{if(!active(token)||!expected.equals(pair))return;if(e!=null||s==null||s.getMetadata().isFromCache()||s.size()!=2){paired=false;partnerData.clear();partnerEvents.clear();publish();return;}
        DocumentSnapshot me=null,other=null;for(DocumentSnapshot m:s.getDocuments())if(m.getId().equals(uid))me=m;else other=m;if(me==null||other==null)return;ownerJoined=me.get("joinedAt");partnerJoined=other.get("joinedAt");partner=other.getId();paired=ownerJoined!=null&&partnerJoined!=null;watchPartner(token,expected);publish();for(String c:CATEGORIES)upload(c);
      }));
    }
    private void watchPartner(long token,String expected){final long generation=++pairEpoch;clearShareListeners();remove(partnerListeners);partnerData.clear();partnerEvents.clear();partnerRevisions.clear();final String other=partner;
      for(String category:CATEGORIES){final String c=category;
        // Consent listener invalidates an already visible copy even when the data did not change.
        partnerListeners.add(db.document("users/"+other+"/careConsent/"+c).addSnapshotListener(MetadataChanges.INCLUDE,(s,e)->{if(!active(token)||generation!=pairEpoch||!expected.equals(pair)||!other.equals(partner))return;partnerData.remove(c);partnerRevisions.remove(c);ListenerRegistration oldListener=shareListeners.remove(c);if(oldListener!=null)oldListener.remove();if(c.equals("roster")){partnerEvents.clear();if(partnerRoster!=null){partnerRoster.remove();partnerRoster=null;}}if(e==null&&s!=null&&s.exists()&&!s.getMetadata().isFromCache()&&Boolean.TRUE.equals(s.getBoolean("enabled"))&&expected.equals(s.getString("pairId"))){Long revision=s.getLong("revision");partnerRevisions.put(c,revision);if(c.equals("roster"))watchPartnerRoster(token,expected,other,revision,generation);shareListeners.put(c,db.document("users/"+other+"/careShares/"+c).addSnapshotListener(MetadataChanges.INCLUDE,(d,issue)->{if(!active(token)||generation!=pairEpoch||!paired||!expected.equals(pair)||!other.equals(partner)||!Objects.equals(partnerRevisions.get(c),revision))return;partnerData.remove(c);if(issue==null&&d!=null&&d.exists()&&!d.getMetadata().isFromCache()&&Objects.equals(d.getLong("consentRevision"),revision))partnerData.put(c,d.getData());publish();}));}publish();}));
      }
    }
    private ListenerRegistration partnerRoster;
    private void watchPartnerRoster(long token,String expected,String other,Long revision,long generation){if(partnerRoster!=null)partnerRoster.remove();partnerRoster=db.collection("users/"+other+"/rosterPublic").whereEqualTo("pairId",expected).whereEqualTo("consentRevision",revision).limit(120).addSnapshotListener(MetadataChanges.INCLUDE,(s,e)->{if(!active(token)||generation!=pairEpoch||!paired||!expected.equals(pair)||!other.equals(partner)||!Objects.equals(partnerRevisions.get("roster"),revision))return;partnerEvents.clear();if(e==null&&s!=null&&!s.getMetadata().isFromCache())for(DocumentSnapshot d:s.getDocuments())partnerEvents.add(d.getData());publish();});}
    @JavascriptInterface public void refresh(){activity.runOnUiThread(()->{bind();publish();});}
    public void onPageReady(){ready=true;refresh();}
    @JavascriptInterface public void setConsent(String category,boolean enabled,String mode,long expectedRevision,String expectedUid){activity.runOnUiThread(()->{if(!uid.equals(expectedUid)||!CATEGORIES.contains(category)||!Arrays.asList("busy","details").contains(mode)||enabled&&!paired)return;final long token=epoch;final String owner=uid,currentPair=pair,other=partner;final Object ownJoin=ownerJoined,otherJoin=partnerJoined;
      DocumentReference ref=own("careConsent",category);db.runTransaction(tx->{DocumentSnapshot old=tx.get(ref);long revision=old.exists()?old.getLong("revision"):0;if(revision!=expectedRevision)throw new IllegalStateException("Consent changed. Refresh before choosing.");Map<String,Object> d=new HashMap<>();d.put("ownerUid",owner);d.put("category",category);d.put("pairId",currentPair);d.put("partnerUid",other);d.put("ownerJoinedAt",ownJoin);d.put("partnerJoinedAt",otherJoin);d.put("revision",revision+1);d.put("enabled",enabled);d.put("mode",mode);d.put("updatedAt",FieldValue.serverTimestamp());tx.set(ref,d);return null;}).addOnSuccessListener(x->{if(!active(token))return;if(!enabled){own("careShares",category).delete();if(category.equals("roster"))deleteRosterShares();}else upload(category);}).addOnFailureListener(x->{if(active(token)){error="Sharing change not confirmed. Connect and retry; other devices keep their last server consent until then.";publish();}});
    });}
    @JavascriptInterface public void updateData(String category,String source,String measuredAt,String origin,String expectedUid){if(source==null||source.length()>4000||!CATEGORIES.contains(category)||category.equals("roster")||!expectedUid.equals(account()))return;activity.runOnUiThread(()->{try{if(!uid.equals(expectedUid))return;JSONObject object=new JSONObject(source);Map<String,Object> data=map(object);Map<String,Object> v=new HashMap<>();v.put("value",data);v.put("measuredAt",Instant.parse(measuredAt).toString());v.put("source",origin.length()<=160?origin:"Manual");lastData.put(category,v);upload(category);}catch(Exception invalid){error="Check the selected sharing data.";publish();}});}
    private boolean consentActive(Map<String,Object> c){return paired&&c!=null&&Boolean.TRUE.equals(c.get("enabled"))&&pair.equals(c.get("pairId"))&&partner.equals(c.get("partnerUid"))&&Objects.equals(ownerJoined,c.get("ownerJoinedAt"))&&Objects.equals(partnerJoined,c.get("partnerJoinedAt"));}
    private void upload(String category){Map<String,Object> consent=consents.get(category),value=lastData.get(category);if(category.equals("roster")){uploadRoster();return;}if(value==null||!consentActive(consent))return;Map<String,Object>d=new HashMap<>(value);d.put("ownerUid",uid);d.put("pairId",pair);d.put("category",category);d.put("consentRevision",consent.get("revision"));d.put("updatedAt",FieldValue.serverTimestamp());final long token=epoch;own("careShares",category).set(d).addOnFailureListener(e->{if(active(token)){error="Shared update pending or rejected. Current server consent always wins.";publish();}});}
    private void deleteRosterShares(){final String owner=uid;db.collection("users/"+owner+"/rosterPublic").limit(150).get(Source.SERVER).addOnSuccessListener(s->{WriteBatch b=db.batch();for(DocumentSnapshot d:s)b.delete(d.getReference());b.commit();});}
    private boolean rosterWriting,rosterDirty;
    private void uploadRoster(){Map<String,Object> c=consents.get("roster");if(rosterWriting){rosterDirty=true;return;}if(!consentActive(c))return;final long token=epoch;final String owner=uid,space=pair,mode=String.valueOf(c.get("mode"));final Object revision=c.get("revision");List<Map<String,Object>> copy=new ArrayList<>(events);rosterWriting=true;
      db.collection("users/"+owner+"/rosterPublic").limit(150).get(Source.SERVER).addOnSuccessListener(s->{if(!active(token)||!space.equals(pair)){rosterWriting=false;return;}WriteBatch b=db.batch();Set<String> keep=new HashSet<>();int count=0;for(Map<String,Object> e:copy){if(Boolean.TRUE.equals(e.get("cancelled"))||++count>120)continue;String id=String.valueOf(e.get("id"));keep.add(id);Map<String,Object> d=new HashMap<>();d.put("id",id);d.put("ownerUid",owner);d.put("pairId",space);d.put("category","roster");d.put("consentRevision",revision);d.put("start",e.get("start"));d.put("end",e.get("end"));d.put("timing",e.get("start") instanceof Number&&e.get("end") instanceof Number?"known":"unknown");d.put("localDate",e.get("localDate")!=null?e.get("localDate"):e.get("start") instanceof Number?Instant.ofEpochMilli(((Number)e.get("start")).longValue()).atZone(java.time.ZoneId.of("Europe/London")).toLocalDate().toString():"");d.put("title",mode.equals("details")?e.get("title"):"");d.put("kind",mode.equals("details")?e.get("kind"):"busy");d.put("updatedAt",FieldValue.serverTimestamp());b.set(db.document("users/"+owner+"/rosterPublic/"+id),d);}for(DocumentSnapshot old:s)if(!keep.contains(old.getId()))b.delete(old.getReference());Map<String,Object> coverage=null;for(Map<String,Object> source:sources)if("complete".equals(source.get("status"))&&source.get("coverageStart") instanceof Number&&source.get("coverageEnd") instanceof Number&&source.get("lastSuccess") instanceof com.google.firebase.Timestamp&&System.currentTimeMillis()-((com.google.firebase.Timestamp)source.get("lastSuccess")).toDate().getTime()<72L*3600000&&copy.size()<=120&&copy.stream().allMatch(event->event.get("start") instanceof Number&&event.get("end") instanceof Number)){coverage=new HashMap<>();coverage.put("start",source.get("coverageStart"));coverage.put("end",source.get("coverageEnd"));break;}DocumentReference coverageRef=db.document("users/"+owner+"/careShares/roster");if(coverage==null)b.delete(coverageRef);else{Map<String,Object>d=new HashMap<>();d.put("ownerUid",owner);d.put("pairId",space);d.put("category","roster");d.put("consentRevision",revision);d.put("value",coverage);d.put("measuredAt",Instant.now().toString());d.put("source","Roster source coverage");d.put("updatedAt",FieldValue.serverTimestamp());b.set(coverageRef,d);}b.commit().addOnCompleteListener(done->{rosterWriting=false;if(rosterDirty){rosterDirty=false;uploadRoster();}if(!done.isSuccessful()&&active(token)){error="Roster sharing is waiting for a confirmed current consent.";publish();}});
      }).addOnFailureListener(e->{rosterWriting=false;});
    }
    @JavascriptInterface public void saveEvent(String source,String expectedUid){if(source==null||source.length()>3000||!expectedUid.equals(account()))return;activity.runOnUiThread(()->{try{if(!uid.equals(expectedUid)||uid.isEmpty())return;JSONObject v=new JSONObject(source);String id=v.optString("id");if(!id.matches("[A-Za-z0-9_-]{1,100}"))return;Map<String,Object>d=new HashMap<>();d.put("id",id);d.put("ownerUid",uid);d.put("origin","manual");d.put("sourceId","manual");d.put("sourceEventId",id);d.put("sourceTimestamp",Instant.now().toString());d.put("kind",v.getString("kind"));d.put("title",v.getString("title"));d.put("start",v.getLong("start"));d.put("end",v.getLong("end"));d.put("timeZone","Europe/London");d.put("cancelled",v.optBoolean("cancelled"));d.put("updatedAt",FieldValue.serverTimestamp());own("rosterEvents",id).set(d).addOnFailureListener(e->{error="Calendar change not saved. Check permissions and reconnect.";publish();});}catch(Exception invalid){error="Check the calendar entry.";publish();}});}
    public void onResume(){activity.runOnUiThread(()->{if(!closed&&ready&&jubileeOwner&&System.currentTimeMillis()-lastJubileeAttempt>15*60000L)refreshJubilee(uid);});}
    @JavascriptInterface public void refreshJubilee(String expectedUid){if(closed||refreshingJubilee||!expectedUid.equals(account())||expectedUid.isEmpty())return;refreshingJubilee=true;lastJubileeAttempt=System.currentTimeMillis();final long token=epoch;FirebaseUser user=auth.getCurrentUser();user.getIdToken(false).addOnSuccessListener(authToken->{if(!active(token)){refreshingJubilee=false;return;}new Thread(()->{java.net.HttpURLConnection connection=null;try{connection=(java.net.HttpURLConnection)new java.net.URL("https://usspace-notify-cb2f5cbc.floot.app/_api/usspace-roster/jubilee-refresh").openConnection();connection.setInstanceFollowRedirects(false);connection.setRequestMethod("POST");connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setRequestProperty("Authorization","Bearer "+authToken.getToken());connection.setRequestProperty("Content-Type","application/json");connection.setDoOutput(true);try(java.io.OutputStream out=connection.getOutputStream()){out.write("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));}int status=connection.getResponseCode();activity.runOnUiThread(()->{if(active(token)){error=status==200?"Jubilee source refreshed. Check coverage and source status below.":"Jubilee integration is unavailable or not yet configured. Your saved roster is kept; the laptop/helper must run.";publish();}});}catch(Exception failure){activity.runOnUiThread(()->{if(active(token)){error="Jubilee refresh failed. Your saved roster is kept.";publish();}});}finally{refreshingJubilee=false;if(connection!=null)connection.disconnect();}},"UsSpace-roster-refresh").start();}).addOnFailureListener(failure->{refreshingJubilee=false;});}
    private static Map<String,Object> map(JSONObject o)throws Exception{Map<String,Object> result=new HashMap<>();for(Iterator<String> keys=o.keys();keys.hasNext();){String k=keys.next();Object v=o.get(k);if(v instanceof JSONObject)v=map((JSONObject)v);if(v==JSONObject.NULL)v=null;result.put(k,v);}return result;}
    private static Object json(Object value)throws Exception{if(value==null)return JSONObject.NULL;if(value instanceof com.google.firebase.Timestamp)return ((com.google.firebase.Timestamp)value).toDate().toInstant().toString();if(value instanceof Map){JSONObject out=new JSONObject();for(Map.Entry<?,?> e:((Map<?,?>)value).entrySet())out.put(String.valueOf(e.getKey()),json(e.getValue()));return out;}if(value instanceof Collection){JSONArray out=new JSONArray();for(Object item:(Collection<?>)value)out.put(json(item));return out;}return value;}
    private void publish(){if(!ready||closed)return;try{JSONObject x=new JSONObject();x.put("uid",uid);x.put("pairId",pair);x.put("paired",paired);x.put("consentConfirmed",consentReady);x.put("partnerUid",partner);x.put("error",error);Map<String,Object> visibleConsent=new HashMap<>();for(Map.Entry<String,Map<String,Object>> row:consents.entrySet()){Map<String,Object> v=new HashMap<>(row.getValue());v.put("current",consentActive(row.getValue()));visibleConsent.put(row.getKey(),v);}x.put("consents",json(visibleConsent));x.put("partnerData",json(partnerData));x.put("events",json(events));x.put("sources",json(sources));x.put("partnerEvents",json(partnerEvents));view.evaluateJavascript("window.onUsPairedCare&&window.onUsPairedCare("+x+");",null);}catch(Exception ignored){}}
    public void close(){closed=true;epoch++;auth.removeAuthStateListener(authListener);remove(accountListeners);clearPair();if(partnerRoster!=null)partnerRoster.remove();}
}
